# Delete one person's data everywhere we copied it (sketch)
def erase_customer(customer_id: str, db, vectors, log_store):
    db.execute("DELETE FROM claims_notes WHERE customer_id = %s", (customer_id,))
    vectors.delete(filter={"customer_id": customer_id})   # chunks carry this tag
    log_store.purge(field="customer_id", value=customer_id)
    # Backups age out on their normal schedule; record that in the response
    return {"customer_id": customer_id, "status": "erased",
            "backups": "expire within 35 days"}
